\title{Real-Rootedness of the Square of the Eulerian Triangle}
\author{Aristotle}
\date{July 10, 2026}

\begin{document}

\begin{abstract}
The Eulerian number $A(n,k)$ counts the permutations of $\{1,\dots,n\}$ with exactly $k$ descents. Arranging these numbers as a lower-triangular array $T$ with $T_{n,k}=A(n,k)$ and squaring the array produces a new triangle with entries $C(n,k)=\sum_j A(n,j)\,A(j,k)$, whose $n$-th row generating polynomial is $B_n(x)=\sum_k C(n,k)\,x^k$. We study whether $B_n$ is \emph{real-rooted}, i.e.\ splits into real linear factors. We prove three results. First, a structural identity, $B_n(x)=\sum_j A(n,j)\,A_j(x)$, exhibiting $B_n$ as a nonnegative Eulerian-weighted combination of the classical Eulerian polynomials $A_j(x)=\sum_k A(j,k)x^k$; this reduces the general real-rootedness conjecture to the \emph{compatibility} (mutual interlacing) of the Eulerian polynomials. Second, an unconditional negativity theorem valid for all $n$: since $B_n$ has nonnegative coefficients and positive constant term $n!$, we have $B_n(x)>0$ for all $x\ge 0$, so every real root of $B_n$ is strictly negative. Third, an explicit certification of real-rootedness for all $n\le 10$, extending the previously known range $n\le 7$ by replacing integer separating brackets --- which fail at $n=8$, where two roots lie in $(-1,0)$ --- with rational brackets. Combining the second and third results, for $n\le 10$ the polynomial $B_n$ splits with all roots real and strictly negative. We describe exact-arithmetic algorithms (Sturm sequences) verifying every claim, and discuss the interlacing infrastructure needed to settle the full conjecture and its generalization to arbitrary powers of the Eulerian triangle.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Eulerian numbers and polynomials}
A \emph{descent} of a permutation $\sigma=\sigma_1\sigma_2\cdots\sigma_n$ of $\{1,\dots,n\}$ is an index $i$ with $\sigma_i>\sigma_{i+1}$. The \textbf{Eulerian number} $A(n,k)$ is the number of permutations of $\{1,\dots,n\}$ with exactly $k$ descents. They satisfy
\[
A(0,0)=1,\qquad A(n,0)=1,\qquad A(n,k)=(k+1)A(n-1,k)+(n-k)A(n-1,k-1),
\]
and vanish for $k<0$ or $k>n-1$ (for $n\ge1$). The first rows are
\[
1;\ \ 1;\ \ 1,1;\ \ 1,4,1;\ \ 1,11,11,1;\ \ 1,26,66,26,1;\ \ 1,57,302,302,57,1.
\]
Each row is symmetric and $\sum_k A(n,k)=n!$.

The \textbf{$n$-th Eulerian polynomial} is $A_n(x)=\sum_{k=0}^n A(n,k)x^k$; e.g.\ $A_0=A_1=1$, $A_2=1+x$, $A_3=1+4x+x^2$, $A_4=1+11x+11x^2+x^3$. A classical theorem (Frobenius) states that every Eulerian polynomial is real-rooted, with all roots simple, negative, and closed under $r\mapsto1/r$. This underlies the log-concavity and unimodality of the Eulerian numbers and the asymptotic normality of the descent statistic.

\subsection{The square of the Eulerian triangle}
Regard the Eulerian numbers as the entries of an infinite lower-triangular matrix $T=(T_{n,k})$, $T_{n,k}=A(n,k)$. The \textbf{square} $T^2$ has entries
\[
C(n,k)=\sum_j A(n,j)\,A(j,k),
\]
and we define its \textbf{$n$-th row generating polynomial} $B_n(x)=\sum_k C(n,k)x^k$. Explicitly,
\begin{align*}
B_0&=1, & B_1&=1, & B_2&=2,\\
B_3&=6+x, & B_4&=24+15x+x^2, & B_5&=120+181x+37x^2+x^3,
\end{align*}
\begin{align*}
B_6 &= 720+2163x+995x^2+83x^3+x^4,\\
B_7 &= 5040+27133x+23739x^2+4613x^3+177x^4+x^5,\\
B_8 &= 40320+364395x+546551x^2+204247x^3+19563x^4+367x^5+x^6,\\
B_9 &= 362880+5272861x+12643559x^2+8090341x^3+1534391x^4+79141x^5+749x^6+x^7,\\
B_{10} &= 3628800+82289163x+300161291x^2+304339263x^3+100211975x^4\\
       &\quad +10633035x^5+312659x^6+1515x^7+x^8.
\end{align*}
Empirically each $B_n$ is monic of degree $n-2$ (for $n\ge2$) with positive integer coefficients and constant term $n!$. The central question is:

\begin{conjecture}[real-rootedness of the squared Eulerian triangle]
For every $n\ge0$, the polynomial $B_n$ is real-rooted.
\end{conjecture}

No general principle guarantees that a product of real-rooted triangular arrays yields real-rooted rows, so the conjecture is genuine. A previous investigation established real-rootedness for $n\le7$ via integer brackets and identified $n=8$ as the boundary of that technique.

\subsection{Contributions}
\begin{enumerate}
\item \textbf{Structural identity} (Theorem~\ref{thm:struct}): $B_n=\sum_j A(n,j)A_j$, reducing the conjecture to compatibility of $(A_j)$.
\item \textbf{Negativity of all roots} (Theorem~\ref{thm:neg}), unconditional: $B_n(x)>0$ for all $x\ge0$, so every real root is strictly negative.
\item \textbf{Certified real-rootedness for $n\le10$} (Theorem~\ref{thm:rr}), past the integer-bracket obstruction at $n=8$; combined with (2), $B_n$ splits with all roots real and negative for $n\le10$ (Theorem~\ref{thm:rrneg}).
\end{enumerate}

\section{Definitions and elementary properties}

\begin{definition}[Eulerian numbers]
$A:\N\times\N\to\N$ is defined by the recurrence of \S1.1. In particular $A(n,0)=1$ for all $n$, and $A(n,k)=0$ whenever $k>n$; the vanishing above the diagonal follows by induction on $n$.
\end{definition}

\begin{definition}[squared triangle]
$C(n,k)=\sum_{j=0}^n A(n,j)A(j,k)$.
\end{definition}

\begin{definition}[row polynomials]
Over $\R$, $A_n(x)=\sum_{k=0}^n A(n,k)x^k$ and $B_n(x)=\sum_{k=0}^n C(n,k)x^k$.
\end{definition}

\begin{definition}[real-rooted]
$p\in\R[x]$ is \emph{real-rooted} if it splits into linear factors over $\R$: $p(x)=a\prod_i(x-r_i)$ with all $r_i\in\R$. Constants and the zero polynomial split trivially.
\end{definition}

\begin{proposition}[shape of $B_n$]\label{prop:shape}
For $n\ge2$, $B_n$ is monic of degree $n-2$ with strictly positive integer coefficients and constant term $C(n,0)=n!$.
\end{proposition}

\begin{proof}
The constant term is $C(n,0)=\sum_j A(n,j)A(j,0)=\sum_j A(n,j)=n!$. The maximal $k$ with a nonzero contribution needs $k\le j-1$ and $j\le n-1$, hence $k\le n-2$, attained only by $(j,k)=(n-1,n-2)$ with $A(n,n-1)=A(n-1,n-2)=1$, so $C(n,n-2)=1$ (monic). Intermediate coefficients are sums of nonnegative terms with at least one positive contribution. Only $C(n,0)\ge1$ is used below.
\end{proof}

\section{The structural identity}

\begin{theorem}[structural identity]\label{thm:struct}
For every $n\ge0$, $\displaystyle B_n(x)=\sum_{j=0}^n A(n,j)\,A_j(x)$.
\end{theorem}

\begin{proof}
By definition,
\[
B_n(x)=\sum_{k=0}^n\Big(\sum_{j=0}^n A(n,j)A(j,k)\Big)x^k
=\sum_{j=0}^n A(n,j)\sum_{k=0}^n A(j,k)x^k,
\]
by interchanging finite sums. Fix $j\le n$. Since $A(j,k)=0$ for $k>j$, the truncated inner sum equals the full Eulerian polynomial: $\sum_{k=0}^n A(j,k)x^k=\sum_{k=0}^j A(j,k)x^k=A_j(x)$. Substituting gives the claim.
\end{proof}

\begin{remark}
Theorem~\ref{thm:struct} realizes $B_n$ as a nonnegative combination of $A_0,\dots,A_n$ with weights $A(n,j)\ge0$. A family of real-rooted polynomials is \emph{compatible} if every nonnegative combination is real-rooted; compatibility follows from mutual interlacing. Hence: if the Eulerian polynomials are compatible, then $B_n$ is real-rooted for every $n$.
\end{remark}

\section{Negativity of the roots (all $n$)}

\begin{lemma}[positivity on the nonnegative axis]\label{lem:pos}
For every $n$ and every real $x\ge0$, $B_n(x)>0$.
\end{lemma}

\begin{proof}
Each coefficient $C(n,k)=\sum_j A(n,j)A(j,k)\ge0$, so for $x\ge0$ every term $C(n,k)x^k\ge0$. The $k=0$ term is $C(n,0)=n!\ge1>0$ and is independent of $x$. Thus $B_n(x)\ge C(n,0)>0$.
\end{proof}

\begin{theorem}[all real roots are negative]\label{thm:neg}
For every $n$, every real root of $B_n$ is strictly negative.
\end{theorem}

\begin{proof}
If $B_n(r)=0$ with $r\in\R$, then $r\ge0$ is impossible by Lemma~\ref{lem:pos} (there $B_n(r)>0$). Hence $r<0$.
\end{proof}

Theorem~\ref{thm:neg} is unconditional and requires no bound on $n$; it localizes every real root to the left of $0$ without asserting that all roots are real.

\section{Certified real-rootedness for $n\le10$}

\subsection{Engines}

\begin{proposition}[quadratic split]\label{prop:quad}
For $b,c\in\R$ with $b^2-4c\ge0$ and $s=\sqrt{b^2-4c}$,
$x^2+bx+c=\big(x-\tfrac{-b+s}{2}\big)\big(x-\tfrac{-b-s}{2}\big)$, which splits over $\R$.
\end{proposition}

\begin{proof}
Expand using $s^2=b^2-4c$; the product equals $x^2+bx+c$ and each linear factor splits.
\end{proof}

\begin{proposition}[splitting from enough distinct real roots]\label{prop:split}
Let $p\in\R[x]$ be nonzero of degree $d$. If $p$ has $d$ distinct real roots, then $p$ splits over $\R$.
\end{proposition}

\begin{proof}
A set of $d$ distinct roots is contained in the finite root set, whose size is at most $\deg p=d$. Hence $p$ has exactly $d$ real roots with multiplicity and splits.
\end{proof}

\begin{proposition}[sign-change root existence]\label{prop:ivt}
If $g:\R\to\R$ is continuous, $a\le b$, and $g(a)g(b)<0$, then $g$ has a zero in $(a,b)$.
\end{proposition}

\begin{proof}
Opposite signs at the endpoints; apply the intermediate value theorem.
\end{proof}

\subsection{Bracketing and the integer obstruction}
To show a degree-$d$ polynomial with positive leading coefficient is real-rooted, it suffices to exhibit a decreasing ladder $t_0>t_1>\cdots>t_d$ with $p(t_{i-1})p(t_i)<0$ for all $i$; then each of the $d$ intervals contains a root (Proposition~\ref{prop:ivt}), the roots are distinct, and $p$ splits (Proposition~\ref{prop:split}).

For $B_n$ the roots are negative (Theorem~\ref{thm:neg}) and, for small $n$, separated enough that the integers $0,-1,-2,\dots$ form a valid ladder; this settles $n\le7$. At $n=8$, however, $B_8$ (degree $6$) has two distinct roots in $(-1,0)$, approximately $-0.7877$ and $-0.1376$; no integer separates them and the integer ladder fails. Refining to \emph{rational} test points (e.g.\ one in $(-1,-\tfrac12)$ and one in $(-\tfrac12,0)$) restores a full alternating ladder. The same refinement handles $n=9,10$, each with two roots in $(-1,0)$.

\begin{theorem}[real-rootedness up to $n=10$]\label{thm:rr}
For every $n\le10$, $B_n$ is real-rooted.
\end{theorem}

\begin{proof}
For $n\le2$, $B_n$ is a nonzero constant. For $n=3$ (linear) it splits automatically; for $n=4$ apply Proposition~\ref{prop:quad} with $15^2-4\cdot24=129\ge0$. For $5\le n\le10$, exhibit a decreasing rational ladder of $n-1$ points at which $B_n$ alternates in sign; Proposition~\ref{prop:ivt} traps a root in each of the $n-2$ intervals, the roots are distinct, and Proposition~\ref{prop:split} concludes. Alternation is a finite exact-arithmetic check.
\end{proof}

\begin{theorem}[split with negative roots up to $n=10$]\label{thm:rrneg}
For every $n\le10$, $B_n$ splits over $\R$ with all roots real and strictly negative.
\end{theorem}

\begin{proof}
Combine Theorem~\ref{thm:rr} (splitting) with Theorem~\ref{thm:neg} (negativity).
\end{proof}

