from functools import lru_cache
from typing import List

@lru_cache(maxsize=None)
def eulerian(n: int, k: int) -> int:
    """Eulerian number A(n,k): permutations of {1,...,n} with k descents."""
    if n == 0:
        return 1 if k == 0 else 0
    if k < 0 or k > n - 1:
        return 0
    if k == 0:
        return 1
    return (k + 1) * eulerian(n - 1, k) + (n - k) * eulerian(n - 1, k - 1)

def sq_coeff(n: int, k: int) -> int:
    """Entry C(n,k) = sum_j A(n,j)*A(j,k) of the squared Eulerian triangle."""
    return sum(eulerian(n, j) * eulerian(j, k) for j in range(n + 1))

def sq_poly(n: int) -> List[int]:
    """Coefficient list of B_n (ascending), trailing zeros removed."""
    c = [sq_coeff(n, k) for k in range(n + 1)]
    while len(c) > 1 and c[-1] == 0:
        c.pop()
    return c

if __name__ == "__main__":
    print("Row polynomials B_n of the squared Eulerian triangle:")
    for n in range(11):
        c = sq_poly(n)
        assert c[0] == __import__("math").factorial(n)     # constant term = n!
        assert c[-1] == 1 or len(c) == 1                   # monic
        print(f"  B_{n:>2}  degree {len(c)-1:>2}  coeffs {c}")

