def eulerian_poly(j: int) -> List[int]:
    """A_j(x) = sum_k A(j,k) x^k."""
    return [eulerian(j, k) for k in range(j + 1)]

def sq_poly(n: int) -> List[int]:
    c = [sum(eulerian(n, j) * eulerian(j, k) for j in range(n + 1))
         for k in range(n + 1)]
    while len(c) > 1 and c[-1] == 0:
        c.pop()
    return c

def _add(a: Sequence[int], b: Sequence[int]) -> List[int]:
    m = max(len(a), len(b))
    return [(a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0)
            for i in range(m)]

def identity_rhs(n: int) -> List[int]:
    """sum_j A(n,j) * A_j(x) as a coefficient list."""
    acc: List[int] = [0]
    for j in range(n + 1):
        acc = _add(acc, [eulerian(n, j) * c for c in eulerian_poly(j)])
    while len(acc) > 1 and acc[-1] == 0:
        acc.pop()
    return acc

if __name__ == "__main__":
    print("Verifying B_n(x) = sum_j A(n,j) * A_j(x):")
    for n in range(13):
        ok = sq_poly(n) == identity_rhs(n)
        print(f"  n={n:>2}: {'OK' if ok else 'MISMATCH'}")
        assert ok
    print("Structural identity verified exactly for all tested n.")

from fractions import Fraction
from functools import lru_cache
from typing import List, Sequence

@lru_cache(maxsize=None)
def eulerian(n: int, k: int) -> int:
    if n == 0:
        return 1 if k == 0 else 0
    if k < 0 or k > n - 1:
        return 0
    if k == 0:
        return 1
    return (k + 1) * eulerian(n - 1, k) + (n - k) * eulerian(n - 1, k - 1)

def sq_poly(n: int) -> List[int]:
    c = [sum(eulerian(n, j) * eulerian(j, k) for j in range(n + 1))
         for k in range(n + 1)]
    while len(c) > 1 and c[-1] == 0:
        c.pop()
    return c

def evalp(c: Sequence[Fraction], x: Fraction) -> Fraction:
    acc = Fraction(0)
    for a in reversed(c):
        acc = acc * x + a
    return acc

def _deriv(a: Sequence[Fraction]) -> List[Fraction]:
    return [a[i] * i for i in range(1, len(a))] or [Fraction(0)]

def _rem(a: List[Fraction], b: List[Fraction]) -> List[Fraction]:
    a = list(a); db = len(b) - 1
    while len(a) - 1 >= db and any(x != 0 for x in a):
        da = len(a) - 1
        lead = a[-1] / b[-1]; shift = da - db
        for i in range(len(b)):
            a[i + shift] -= lead * b[i]
        while len(a) > 1 and a[-1] == 0:
            a.pop()
        if len(a) - 1 == da:
            break
    while len(a) > 1 and a[-1] == 0:
        a.pop()
    return a

def sturm_chain(coeffs: Sequence[int]) -> List[List[Fraction]]:
    p0 = [Fraction(c) for c in coeffs]; p1 = _deriv(p0)
    chain = [p0, p1]
    while len(chain[-1]) > 1 or chain[-1][0] != 0:
        r = _rem(chain[-2], chain[-1])
        if len(r) == 1 and r[0] == 0:
            break
        chain.append([-c for c in r])
    return chain

def _signchanges(vals: Sequence[Fraction]) -> int:
    ch = 0; prev = 0
    for v in vals:
        s = (v > 0) - (v < 0)
        if s != 0:
            if prev != 0 and s != prev:
                ch += 1
            prev = s
    return ch

def count_roots(coeffs: Sequence[int], a: Fraction, b: Fraction) -> int:
    chain = sturm_chain(coeffs)
    return _signchanges([evalp(p, a) for p in chain]) - \
           _signchanges([evalp(p, b) for p in chain])

if __name__ == "__main__":
    print("Exact real-root count (Sturm's theorem):")
    for n in range(3, 11):
        c = sq_poly(n); deg = len(c) - 1
        M = 1 + max(abs(x) for x in c) / abs(c[-1])
        lo, hi = Fraction(-M) - 1, Fraction(M) + 1
        nroots = count_roots(c, lo, hi)
        in_unit = count_roots(c, Fraction(-1), Fraction(0))
        print(f"  n={n:>2}: degree {deg}, real roots {nroots} "
              f"(real-rooted={nroots == deg}), roots in (-1,0): {in_unit}")
        assert nroots == deg
    print("Every B_n (3<=n<=10) is real-rooted; the (-1,0) count reaches 2 at n=8.")

