    if k < 0 or k > n-1: return 0
    if k == 0: return 1
    return (k+1)*EULERIAN(n-1,k) + (n-k)*EULERIAN(n-1,k-1)

function SQ_COEFF(n, k):
    return sum over j in 0..n of EULERIAN(n,j)*EULERIAN(j,k)

function SQ_POLY(n):
    C <- [SQ_COEFF(n,k) for k in 0..n]
    strip trailing zeros of C
    return C            # ascending coefficients of B_n

